        VotingOnlyNodePlugin_fullMasterWithOlderState(
                new Object() {
                    public final String localAcceptedTerm   = "42";
                    public final String localAcceptedVersion = "7";
                }
        );

// 3. Use the predicate on a Join instance
Join someJoin = ...;          // obtain a Join object from your cluster
boolean matches = isFullMasterWithOlderState.test(someJoin);

System.out.println("Is this Join a full master with an older state? " + matches);
```

